upstream health_checked {
    zone upstream_health 128k;
    server 10.0.0.10:8080 max_fails=3 fail_timeout=30s slow_start=30s;
    server 10.0.0.11:8080 max_fails=3 fail_timeout=30s slow_start=30s;
    server 10.0.0.12:8080 backup;
}
server {
    listen 80;
    server_name health.example.com;
    location / {
        proxy_pass http://health_checked;
        health_check interval=5s fails=3 passes=2 uri=/health;
        health_check_timeout 3s;
    }
}

upstream zone_sync {
    zone backend 256k;
    server 10.0.0.10:8080;
    server 10.0.0.11:8080;
    server 10.0.0.12:8080;
    sticky cookie srv_id expires=1h domain=.example.com path=/;
}
server {
    listen 80;
    server_name zone.example.com;
    location / {
        proxy_pass http://zone_sync;
    }
}

stream {
    upstream stream_backend {
        zone tcp_lb 64k;
        least_conn;
        server 10.0.0.60:3306;
        server 10.0.0.61:3306;
    }
    server {
        listen 3306;
        proxy_pass stream_backend;
        proxy_connect_timeout 5s;
    }
}

upstream with_health_check {
    zone backend 128k;
    server 10.0.0.10:8080 slow_start=60s;
    server 10.0.0.11:8080 slow_start=60s;
}
server {
    listen 80;
    location / {
        proxy_pass http://with_health_check;
        health_check interval=10s jitter=2s uri=/health;
        health_check_status 200 302;
    }
    location /status {
        health_check_status;
    }
}

upstream slow_start {
    zone slow_start 128k;
    server 10.0.0.10:8080 slow_start=120s;
    server 10.0.0.11:8080 slow_start=120s;
    server 10.0.0.12:8080 slow_start=60s backup;
}

server {
    listen 8080;
    server_name _;
    location /status {
        stub_status;
        allow 127.0.0.1;
        allow 10.0.0.0/8;
        deny all;
    }
}

upstream session_sticky {
    zone sticky 64k;
    server 10.0.0.10:8080;
    server 10.0.0.11:8080;
    server 10.0.0.12:8080;
    sticky learn
        create=$upstream_cookie_exampleid
        lookup=$cookie_exampleid
        zone=client_sessions:1m
        timeout=1h;
